TODO 1  Printer(print_doc) / Scanner(scan_doc) / Faxer(fax_doc) + 선택 Stapler(staple_doc), 모두 @runtime_checkable Protocol
TODO 2  OldPrinter 에서 NotImplementedError 메서드 3개 삭제 + Machine 상속 제거
TODO 3  print_report(m: Printer), archive_scan(m: Scanner), send_permission_fax(m: Faxer)
점검 진행: 처음 1/4 -> TODO1 뒤 2/4 -> TODO2 뒤 3/4 -> TODO3 뒤 4/4

실행: python3 s2_office_machine_solution.py   ('통과 4 / 4')

이 파일은 시작 코드 원본에서 TODO 구역만 채운 것이다. 점검 구역은 원본과 한 글자도 다르지 않다.
"""
from abc import ABC, abstractmethod
from typing import Protocol, runtime_checkable, get_type_hints  # noqa: F401 (TODO에서 사용)


# ---------------------------------------------------------------
# 지금의 설계: 모든 기기가 지켜야 하는 '큰 약속' 하나
# ---------------------------------------------------------------
class Machine(ABC):
    """사무기기 약속: 출력, 스캔, 팩스, 스테이플을 모두 할 수 있다."""

    @abstractmethod
    def print_doc(self, doc: str) -> str: ...

    @abstractmethod
    def scan_doc(self, doc: str) -> str: ...

    @abstractmethod
    def fax_doc(self, doc: str, number: str) -> str: ...

    @abstractmethod
    def staple_doc(self, doc: str) -> str: ...


# TODO(학생) 1: 여기에 쓰는 쪽(클라이언트)이 실제로 필요한 만큼의 작은 약속을 정의하세요.
#   - 이름은 Printer, Scanner, Faxer 로 한다. (스테이플은 어디에 둘지 스스로 정한다.)
#   - typing.Protocol 을 사용하고, isinstance 로 검사할 수 있게 @runtime_checkable 을 붙인다.
#   - Protocol 안의 메서드 몸체는 ... 로 둔다.
# [정답] 분리 기준 = 각 클라이언트가 실제로 부르는 메서드 묶음.
@runtime_checkable
class Printer(Protocol):
    def print_doc(self, doc: str) -> str: ...


@runtime_checkable
class Scanner(Protocol):
    def scan_doc(self, doc: str) -> str: ...


@runtime_checkable
class Faxer(Protocol):
    def fax_doc(self, doc: str, number: str) -> str: ...


# 스테이플: 지금 쓰는 클라이언트가 없다. Printer 에 넣으면 OldPrinter 가 다시 못 지키므로 따로 둔다.
@runtime_checkable
class Stapler(Protocol):
    def staple_doc(self, doc: str) -> str: ...


class SmartMFP(Machine):
    """학교에서 새로 들여온 복합기: 모든 기능이 있다."""

    def print_doc(self, doc: str) -> str:
        return f"[복합기] 출력: {doc}"

    def scan_doc(self, doc: str) -> str:
        return f"[복합기] 스캔 파일: {doc}.pdf"

    def fax_doc(self, doc: str, number: str) -> str:
        return f"[복합기] 팩스 {number} 로 전송: {doc}"

    def staple_doc(self, doc: str) -> str:
        return f"[복합기] 스테이플 완료: {doc}"


# TODO(학생) 2: OldPrinter 를 정리하세요.
#   - 할 수 없는 기능을 억지로 '구현'한 메서드를 없앤다.
#   - 메서드를 없애면 Machine 을 상속한 채로는 객체를 만들 수 없다. 왜 그런지 생각해 보고 해결한다.
# [정답] Machine 상속을 없앤다. Machine 은 ABC 라서 추상 메서드를 하나라도 안 만들면 객체를 못 만든다.
#        Protocol 은 구조적 타이핑이므로 print_doc 모양만 맞으면 Printer 약속을 지킨 것이다.
class OldPrinter:
    """동아리방 구석의 구형 흑백 프린터: 출력만 할 수 있다."""

    def print_doc(self, doc: str) -> str:
        return f"[구형 프린터] 출력: {doc}"


# ---------------------------------------------------------------
# 기기를 '쓰는 쪽'(클라이언트) 함수들
# ---------------------------------------------------------------
# TODO(학생) 3: 각 함수가 실제로 부르는 메서드를 보고, 타입 힌트 Machine 을 알맞은 작은 Protocol 로 바꾸세요.
def print_report(m: Printer) -> str:
    """동아리 활동 보고서를 출력한다."""
    return m.print_doc("동아리 활동 보고서")


def archive_scan(m: Scanner) -> str:
    """지난 실험 노트를 스캔해 보관한다."""
    return m.scan_doc("실험노트_3월")


def send_permission_fax(m: Faxer) -> str:
    """대회 참가 동의서를 팩스로 보낸다."""
    return m.fax_doc("참가 동의서", "02-123-4567")


# ---------------------------------------------------------------
# 점검 (고치지 마세요)
# ---------------------------------------------------------------
def _try(label: str, fn) -> bool:
    try:
        ok, msg = fn()
    except Exception as e:  # 미완성 상태의 오류를 안내 메시지로 바꾼다
        ok, msg = False, f"{type(e).__name__}: {e}"
    print(f"  [{'통과' if ok else '미완성'}] {label}" + ("" if ok else f"  -> {msg}"))
    return ok


def check_protocols():
    names = [n for n in ("Printer", "Scanner", "Faxer") if n not in globals()]
    if names:
        return False, f"{', '.join(names)} 가 아직 없어요 (TODO 1)"
    if not isinstance(SmartMFP(), globals()["Scanner"]):
        return False, "isinstance(SmartMFP(), Scanner) 가 False 예요. @runtime_checkable 을 확인하세요"
    return True, ""


def check_old_printer():
    p = OldPrinter()  # Machine 을 상속한 채 메서드를 지우면 여기서 TypeError
    left = [n for n in ("scan_doc", "fax_doc", "staple_doc") if hasattr(p, n)]
    if left:
        return False, f"OldPrinter 에 아직 {', '.join(left)} 가 있어요 (TODO 2)"
    return print_report(p) == "[구형 프린터] 출력: 동아리 활동 보고서", "print_report 결과가 달라졌어요"


def check_hints():
    want = {print_report: "Printer", archive_scan: "Scanner", send_permission_fax: "Faxer"}
    for fn, proto in want.items():
        hint = get_type_hints(fn)["m"]
        if hint is not globals().get(proto):
            return False, f"{fn.__name__} 의 m 이 아직 {getattr(hint, '__name__', hint)} 예요 (TODO 3)"
    return True, ""


def check_smart_mfp_still_works():
    m = SmartMFP()
    got = (print_report(m), archive_scan(m), send_permission_fax(m))
    want = ("[복합기] 출력: 동아리 활동 보고서",
            "[복합기] 스캔 파일: 실험노트_3월.pdf",
            "[복합기] 팩스 02-123-4567 로 전송: 참가 동의서")
    return got == want, f"SmartMFP 결과가 달라졌어요: {got}"


if __name__ == "__main__":
    print("== 지금 상태 그대로 실행해 보기 ==")
    for client in (print_report, archive_scan, send_permission_fax):
        for cls in (SmartMFP, OldPrinter):
            try:
                machine = cls()  # 객체를 만들 수 없는 상태도 메시지로 보여 준다
            except Exception as e:
                print(f"  {cls.__name__}() 객체를 만들 수 없음 -> {type(e).__name__}: {e}")
                continue
            try:
                print(f"  {client.__name__}({cls.__name__}) -> {client(machine)}")
            except Exception as e:
                print(f"  {client.__name__}({cls.__name__}) -> 예외 {type(e).__name__}: {e}")

    print("\n== 점검 ==")
    results = [
        _try("TODO 1: Printer/Scanner/Faxer Protocol 정의", check_protocols),
        _try("TODO 2: OldPrinter 에 못 하는 기능이 남아 있지 않다", check_old_printer),
        _try("TODO 3: 클라이언트가 작은 Protocol 에만 의존한다", check_hints),
        _try("기존 기능 유지: SmartMFP 는 여전히 모든 클라이언트에 쓸 수 있다", check_smart_mfp_still_works),
    ]
    print(f"\n통과 {sum(results)} / {len(results)}")
    if all(results):
        print("모두 통과! 학습지 활동 2-4의 질문에 답하세요.")

s3_transfer_weather.py:
"""3차시 활동 3-6: 기상 관측소 모범 판단 예시

학생 활동은 '읽기·화살표·판단'이므로 이 코드는 채점 대상이 아니라 교사 설명용 예시다.
판단
    역전한다    : WeatherStation -> ThermoSensorV2
                  근거: V3 교체 예정 + 메서드 이름이 바뀜(read -> measure_celsius) + 교실에서 실제 센서로 시험 불가
    역전 안 한다: WeatherStation -> CsvWriter
                  근거: CSV 외 저장 계획 없음, 구현 1개, 지금 시험에도 문제 없음 -> 추상은 비용(YAGNI)
약속 이름은 고수준(WeatherStation)이 필요로 하는 말: TemperatureSource.current_celsius() -> float
V3 의 이름 차이는 어댑터(ThermoSensorV3Adapter)가 흡수한다. WeatherStation 은 V2/V3 를 모른다.

실행: python3 s3_transfer_weather_solution.py
"""
from typing import Protocol


class TemperatureSource(Protocol):
    """고수준이 필요한 약속: 지금 기온(섭씨)을 돌려준다."""
    def current_celsius(self) -> float: ...


class ThermoSensorV2:
    def read(self) -> float:
        return 18.5


class ThermoSensorV3:  # 다음 학기 장치(메서드 이름이 다르다)
    def measure_celsius(self) -> float:
        return 19.0


class V2Adapter:
    def __init__(self, sensor: ThermoSensorV2) -> None:
        self.sensor = sensor

    def current_celsius(self) -> float:
        return self.sensor.read()


class V3Adapter:
    def __init__(self, sensor: ThermoSensorV3) -> None:
        self.sensor = sensor

    def current_celsius(self) -> float:
        return self.sensor.measure_celsius()


class FixedTemperature:
    """교실 시험용 가짜 센서."""
    def __init__(self, value: float) -> None:
        self.value = value

    def current_celsius(self) -> float:
        return self.value


class CsvWriter:  # 그대로 둔다 (역전하지 않는 의존)
    def __init__(self) -> None:
        self.rows: list[str] = []

    def write(self, row: list) -> None:
        line = ",".join(str(v) for v in row)
        self.rows.append(line)
        print(f"  CSV 기록: {line}")


class WeatherStation:
    HOT = 30.0

    def __init__(self, source: TemperatureSource) -> None:
        self.source = source          # 역전: 약속에만 의존
        self.writer = CsvWriter()     # 유지: 바뀔 계획 없는 구체 의존(의도적 비적용)

    def record(self, hour: int) -> None:
        temp = self.source.current_celsius()
        status = "경고" if temp >= self.HOT else "정상"
        self.writer.write([hour, temp, status])


if __name__ == "__main__":
    s = WeatherStation(V2Adapter(ThermoSensorV2()))      # 이번 학기 조립
    s.record(9)
    assert s.writer.rows == ["9,18.5,정상"]
    s3 = WeatherStation(V3Adapter(ThermoSensorV3()))     # 다음 학기: WeatherStation 수정 0줄
    s3.record(10)
    assert s3.writer.rows == ["10,19.0,정상"]
    t = WeatherStation(FixedTemperature(31.0))           # 교실 시험: 실제 센서 없이 '경고' 규칙 확인
    t.record(14)
    assert t.writer.rows == ["14,31.0,경고"]
    print("역전 예시 assert 모두 통과 (V2/V3/가짜 센서 교체 시 WeatherStation 수정 0줄)")
